function validPath(n, edges, source, destination) {
  const reachable = new Set([source]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [a, b] of edges) {
      if (reachable.has(a) && !reachable.has(b)) { reachable.add(b); changed = true; }
      else if (reachable.has(b) && !reachable.has(a)) { reachable.add(a); changed = true; }
    }
  }
  return reachable.has(destination);
}

